      SUBROUTINE FIX23HCC     REVISE REFERENCES FOR ALGEBRAIC OPERATIONS FOLLOWING PRESENT ELEMENTCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2D.CIN'      INCLUDE 'ELM24D.CIN'      INCLUDE 'LIMITS.CIN'CC     LOCAL VARIABLESC      INTEGER         TYPET      EQUIVALENCE     (FAKE,LAKE)      EXTERNAL        IDATACC------------------------------------------------------------------------C      NN = NUM      KRCOM = II + 1C   10 NN = NN + 1      III = ISTOR(NN)      TYPET = IDATA(III)      IF (TYPET .LE. 0 .OR. TYPET .GE. 50) GO TO 6000      CALL SKETCH(NN)      IF (TYPET .EQ. 2 .OR. TYPET .EQ. 3 .OR. TYPET .EQ. 4     1    .OR. TYPET .EQ. 5 .OR. TYPET .EQ. 7 .OR. TYPET .EQ. 8     2    .OR. TYPET .EQ. 11 .OR. TYPET .EQ. 14 .OR. TYPET .EQ. 16     3    .OR. TYPET .EQ. 18 .OR. TYPET .EQ. 19 .OR. TYPET .EQ. 20     4    .OR. TYPET .EQ. 25 .OR. TYPET .EQ. 28 .OR. TYPET .EQ. 29     5    .OR. TYPET .EQ. 30 .OR. TYPET .EQ. 34 .OR. TYPET .EQ. 35     6    .OR. TYPET .EQ. 36 .OR. TYPET .EQ. 42) GO TO 100      IF (TYPET .EQ. 23) GO TO 2300      GO TO 6000CC     PHYSICAL ELEMENTC  100 DO 110 J = 1, NPARMS      IADR = III + J      KREG = IDATA(IADR)      KTIE = TIE(IADR)      IF (KTIE .EQ. 100 .AND. KREG .EQ. KRCOM) THEN        KREG = I + 1        LAKE = KREG        DATA(IADR) = FAKE      ENDIF  110 CONTINUE      GO TO 6000CC     23. -- ALGEBRAIC OPERATIONC 2300 K1REG = IDATA(III+1)      K2REG = IDATA(III+2)      JREG = IDATA(III+4)      K1TIE = TIE(III+1)      K2TIE = TIE(III+2)      JTIE = TIE(III+4)      KRCOM = II + 1      IF (K1TIE .EQ. 100 .AND. K1REG .EQ. KRCOM) K1REG = I + 1      IF (K2TIE .EQ. 100 .AND. K2REG .EQ. KRCOM) K2REG = I + 1      IF (JTIE .EQ. 100 .AND. JREG .EQ. KRCOM) JREG = I + 1      LAKE = K1REG      DATA(III+1) = FAKE      LAKE = K2REG      DATA(III+2) = FAKE      LAKE = JREG      DATA(III+4) = FAKE      GO TO 6000C 6000 IF (NN .LT. NELLIM) GO TO 10C 6200 RETURN      END